mapper.update:
UPDATE ai_task_step
SET status = 'RUNNING', attempts = attempts + 1, started_at = now(), updated_at = now(),
    error_code = NULL, error_message = NULL
WHERE run_id = #{runId}
  AND step_no = #{stepNo}
  AND status IN ('PENDING', 'FAILED', 'RUNNING')

UPDATE ai_task_step
SET args_json = #{argsJson}, updated_at = now()
WHERE run_id = #{runId}
  AND step_no = #{stepNo}

UPDATE ai_task_step
SET status = 'SUCCEEDED', result_summary = #{summary}, result_json = #{resultJson},
    evidence_json = #{evidenceJson}, cost_ms = #{costMs}, finished_at = now(),
    error_code = NULL, error_message = NULL, updated_at = now()
WHERE run_id = #{runId}
  AND step_no = #{stepNo}

UPDATE ai_task_step
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage},
    cost_ms = #{costMs}, finished_at = now(), updated_at = now()
WHERE run_id = #{runId}
  AND step_no = #{stepNo}

UPDATE ai_task_step
SET status = 'SKIPPED', error_code = 'UPSTREAM_FAILED',
    error_message = '前序步骤失败，本步未执行', finished_at = now(), updated_at = now()
WHERE run_id = #{runId}
  AND step_no >= #{fromStepNo}
  AND status = 'PENDING'

UPDATE ai_task_step
SET status = 'CANCELLED', finished_at = now(), updated_at = now()
WHERE status IN ('PENDING', 'RUNNING')
  AND run_id IN (
      SELECT id FROM ai_task_run
      WHERE user_id = #{userId}
        AND conversation_id = #{conversationId}
        AND status = 'CANCELLED'
  )
